"""Credential-free request evidence capture."""

import hashlib
import json

from .extraction import ExtractionError, build_messages, validate_extraction


def write_evidence(app, responder=None, response_source=None):
    raw = (app.source / "IT-001.json").read_bytes()
    message = json.loads(raw)["message"]
    messages = build_messages("IT-001.json", message)
    captured = {}
    content, failure = None, None
    try:
        content = responder(messages) if responder else app.extractor.call(messages, captured.update)
    except ExtractionError as exc:
        failure = str(exc)
    parsed = json.loads(content) if content else None
    evidence = {
        "generated_at": app.now(),
        "observation": {"type": "mock" if responder else "provider",
                        "response_source": response_source or f"{app.extractor.config['provider']}/{app.extractor.config['model']}",
                        "document_id": "IT-001.json", "source_sha256": hashlib.sha256(raw).hexdigest()},
        "request": {"method": "POST", "url": "<workspace-url>/ai-gateway/mlflow/v1/chat/completions",
                    "headers": {"Authorization": "Bearer <redacted>", "Content-Type": "application/json"},
                    "body": app.extractor.body(messages)},
        "configuration": {k: v for k, v in app.extractor.config.items() if k != "base_url"},
        "response": {"http_status": captured.get("http_status"), "content_parsed": parsed},
        "handling_outcome": {"error": failure, "validation": validate_extraction(parsed, message) if parsed else None},
        "response_handling": "HTTP errors: retry 429/5xx and transport failures; reject refusals and truncation; "
                             "require finish_reason stop, JSON object, schema, dates and exact source quotes; "
                             "see intake/provider.py and offline tests for implemented handling.",
    }
    app.atomic_write(app.output / "request-evidence.json", json.dumps(evidence, indent=2) + "\n")
    return {"evidence": str(app.output / "request-evidence.json"), "error": failure}

