from .provider import now


class Store:
    def __init__(self, path):
        self.path = Path(path)
        absolute = self.path.resolve()
        if any(absolute == root or root in absolute.parents for root in map(Path, ("/Workspace", "/Volumes", "/dbfs"))):
            raise ValueError("SQLite state must use local persistent disk, not Databricks Workspace/Volumes/DBFS")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with closing(self.connect()) as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS batches (
                    id TEXT PRIMARY KEY, created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS jobs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    document_id TEXT NOT NULL, sha TEXT NOT NULL,
                    raw BLOB NOT NULL, fingerprint TEXT NOT NULL,
                    state TEXT NOT NULL, token TEXT, lease_until REAL,
                    created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS batch_jobs (
                    batch_id TEXT NOT NULL, job_id INTEGER NOT NULL,
                    reused INTEGER NOT NULL DEFAULT 0,
                    PRIMARY KEY (batch_id, job_id)
                );
                CREATE TABLE IF NOT EXISTS desired (
                    document_id TEXT PRIMARY KEY, job_id INTEGER NOT NULL
                );
                CREATE TABLE IF NOT EXISTS current (
                    document_id TEXT PRIMARY KEY, record TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS attempts (
                    id TEXT PRIMARY KEY, job_id INTEGER,
                    applied INTEGER NOT NULL, record TEXT NOT NULL
                );
                CREATE INDEX IF NOT EXISTS jobs_state ON jobs(state, lease_until);
                CREATE TABLE IF NOT EXISTS policy_versions (
                    version TEXT PRIMARY KEY, metadata TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS active_policy (
                    id INTEGER PRIMARY KEY CHECK (id=1), metadata TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS routing_events (
                    id TEXT PRIMARY KEY, record TEXT NOT NULL
                );
            """)
        # Additive migration of databases created by steps 1–4. Serialize the
        # inspection and ALTERs so simultaneous operator startup is safe.
        with self.transaction() as db:
            columns = {r["name"] for r in db.execute("PRAGMA table_info(jobs)")}
            for column in ("input_error", "processing_config"):
                if column not in columns:
                    db.execute(f"ALTER TABLE jobs ADD COLUMN {column} TEXT")

    def connect(self):
        db = sqlite3.connect(self.path, timeout=30, isolation_level=None)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA synchronous=FULL")
        return db

    @contextmanager
    def transaction(self, write=True):
        db = self.connect()
        try:
            db.execute("BEGIN IMMEDIATE" if write else "BEGIN")
            yield db
            db.commit()
        except BaseException:
            db.rollback()
            raise
        finally:
            db.close()

    @staticmethod
    def records(db):
        return {row["document_id"]: json.loads(row["record"])
                for row in db.execute("SELECT * FROM current ORDER BY document_id")}

    @staticmethod
    def put_current(db, record):
        db.execute("INSERT OR REPLACE INTO current VALUES (?, ?)",
                   (record["document_id"], json.dumps(record)))

    def current(self):
        with self.transaction(False) as db:
            return self.records(db)

    @staticmethod
    def route_current_policy(db, record, route):
        row = db.execute("SELECT metadata FROM active_policy WHERE id=1").fetchone()
        return route(record, policy=json.loads(row[0]) if row else None)

    def reroute(self, db, record, route, policy=None):
        fields = ("status", "owner", "next_action", "routing_reasons", "policy_version", "routing_version", "policy_sha256")
        before = {k: record.get(k) for k in fields}
        routing = route(record, policy=policy) if policy else self.route_current_policy(db, record, route)
        after = {k: routing.get(k) for k in fields}
        if before == after:
            return False
        event_id = uuid.uuid4().hex
        path = f"routing-history/{record['document_id']}/{event_id}.json"
        event = {"document_id": record["document_id"], "source_sha256": record["source_sha256"],
                 "extraction_history_file": record["history_file"], "changed_at": now(),
                 "before": before, "after": after, "history_file": path,
                 "previous_routing_history_file": record.get("routing_history_file")}
        db.execute("INSERT INTO routing_events VALUES (?,?)", (event_id, json.dumps(event)))
        record.update(routing, routing_history_file=path)
        self.put_current(db, record)
        return True

    def activate_policy(self, load_policy, route, refresh=False):
        changed = []
        with self.transaction() as db:
            # Read files while holding the state lock: an old operator cannot
            # activate a cached earlier policy after a newer activation.
            policy = load_policy()
            db.execute("INSERT OR IGNORE INTO policy_versions VALUES (?,?)", (policy["version"], json.dumps(policy)))
            db.execute("INSERT OR REPLACE INTO active_policy VALUES (1,?)", (json.dumps(policy),))
            if refresh:
                for doc, record in self.records(db).items():
                    if self.reroute(db, record, route, policy):
                        changed.append(doc)
        return {"policy": policy, "refreshed": changed}

    def submit(self, sources, fingerprint, route, force=False, processing_config=None):
        """Register byte snapshots atomically; later accepted revisions win.

        Identical active work is shared. Each batch keeps its own membership,
        including reused and superseded work, for progress and resumption.
        """
        batch = uuid.uuid4().hex
        with self.transaction() as db:
            db.execute("INSERT INTO batches VALUES (?, ?)", (batch, now()))
            current = self.records(db)
            seen = set()
            for source in sources:
                doc, raw = source[:2]
                input_error = source[2] if len(source) > 2 else None
                if doc in seen:
                    raise ValueError(f"duplicate document_id in batch: {doc}")
                seen.add(doc)
                sha = hashlib.sha256(raw).hexdigest() if raw is not None else ""
                active = db.execute("SELECT j.* FROM desired d JOIN jobs j ON j.id=d.job_id WHERE d.document_id=?", (doc,)).fetchone()
                same_active = active and active["sha"] == sha and active["input_error"] == input_error and active["fingerprint"] == fingerprint and active["state"] in ("pending", "running")
                if same_active and not force:
                    job_id, reused = active["id"], False
                else:
                    old = current.get(doc)
                    reused = bool(raw is not None and not force and old and old.get("error") is None
                                  and old.get("extraction") is not None
                                  and old.get("source_sha256") == sha
                                  and old.get("settings_fingerprint") == fingerprint)
                    job_id = db.execute("INSERT INTO jobs(document_id,sha,raw,fingerprint,state,created_at,input_error,processing_config) VALUES (?,?,?,?,?,?,?,?)",
                                        (doc, sha, raw if raw is not None else b"", fingerprint, "done" if reused else "pending", now(), input_error,
                                         json.dumps(processing_config) if processing_config else None)).lastrowid
                    if active:
                        db.execute("UPDATE jobs SET state='superseded', token=NULL, lease_until=NULL WHERE id=? AND state IN ('pending','running')", (active["id"],))
                    db.execute("INSERT OR REPLACE INTO desired VALUES (?,?)", (doc, job_id))
                    if reused:
                        self.reroute(db, old, route)
                db.execute("INSERT INTO batch_jobs VALUES (?,?,?)", (batch, job_id, int(reused)))
        return batch

    def claim(self, batch, fingerprint, lease_seconds):
        token = uuid.uuid4().hex
        timestamp = time.time()
        with self.transaction() as db:
            row = db.execute("""SELECT j.* FROM jobs j
                JOIN batch_jobs b ON b.job_id=j.id
                JOIN desired d ON d.job_id=j.id
                WHERE b.batch_id=? AND j.fingerprint=?
                AND (j.state='pending' OR (j.state='running' AND j.lease_until < ?))
                ORDER BY j.id LIMIT 1""", (batch, fingerprint, timestamp)).fetchone()
            if row is None:
                return None
            db.execute("UPDATE jobs SET state='running',token=?,lease_until=? WHERE id=?",
                       (token, timestamp + lease_seconds, row["id"]))
            return {**dict(row), "token": token}

    def renew(self, job, lease_seconds):
        with self.transaction() as db:
            timestamp = time.time()
            changed = db.execute("UPDATE jobs SET lease_until=? WHERE id=? AND token=? AND state='running' AND lease_until>=?",
                                 (timestamp + lease_seconds, job["id"], job["token"], timestamp)).rowcount
            return bool(changed)

    def complete(self, job, record, route):
        attempt_id = uuid.uuid4().hex
        record = dict(record)
        record["revision"] = job["id"]
        record["history_file"] = f"history/{record['document_id']}/{attempt_id}.json"
        with self.transaction() as db:
            record.update(self.route_current_policy(db, record, route))
            live = db.execute("SELECT j.*, d.job_id AS desired_id FROM jobs j LEFT JOIN desired d ON d.document_id=j.document_id WHERE j.id=?", (job["id"],)).fetchone()
            applied = bool(live and live["token"] == job["token"]
                           and live["state"] == "running" and live["desired_id"] == job["id"]
                           and live["lease_until"] >= time.time())
            old_row = db.execute("SELECT record FROM current WHERE document_id=?", (record["document_id"],)).fetchone()
            old = json.loads(old_row[0]) if old_row else None
            record["last_success"] = None
            if record["error"] and old:
                record["last_success"] = ({k: old.get(k) for k in (
                    "history_file", "source_sha256", "settings_fingerprint", "extracted_at", "response_source")}
                    if old.get("error") is None else old.get("last_success"))
            db.execute("INSERT INTO attempts VALUES (?,?,?,?)", (attempt_id, job["id"], int(applied), json.dumps(record)))
            if applied:
                self.put_current(db, record)
                db.execute("UPDATE jobs SET state=?,token=NULL,lease_until=NULL WHERE id=?",
                           ("failed" if record["error"] else "done", job["id"]))
        return applied

    def progress(self, batch=None):
        with self.transaction(False) as db:
            if batch and not db.execute("SELECT 1 FROM batches WHERE id=?", (batch,)).fetchone():
                raise ValueError(f"unknown batch: {batch}")
            rows = db.execute("""SELECT j.*, b.reused, b.batch_id FROM jobs j
                JOIN batch_jobs b ON b.job_id=j.id WHERE b.batch_id=? ORDER BY j.id""", (batch,)).fetchall() if batch else db.execute("SELECT *, 0 AS reused FROM jobs ORDER BY id").fetchall()
            counts = {s: 0 for s in ("pending", "running", "completed", "failed", "superseded", "reused")}
            items = []
            for row in rows:
                state = "completed" if row["state"] == "done" else row["state"]
                counts[state] += 1
                counts["reused"] += row["reused"]
                items.append({"document_id": row["document_id"], "revision": row["id"],
                              "source_sha256": row["sha"] or None, "state": state,
                              "lease_expired": state == "running" and row["lease_until"] < time.time(),
                              "settings_fingerprint": row["fingerprint"], "input_error": row["input_error"],
                              "processing_config": json.loads(row["processing_config"]) if row["processing_config"] else None})
            return {"batch_id": batch, "counts": counts, "items": items}

    def batches(self):
        with self.transaction(False) as db:
            return [dict(r) for r in db.execute("SELECT * FROM batches ORDER BY created_at DESC")]
"""Run with python -m intake; offline operation needs no installation."""

import argparse
import json
from pathlib import Path

from .app import Intake
from .extraction import ROOT


def main():
    parser = argparse.ArgumentParser(description="Durable IT access-request intake")
    subs = parser.add_subparsers(dest="command", required=True)
    for name in ("intake", "resume", "retry", "refresh-policy", "queue", "status", "export", "verify", "migrate", "accuracy", "evidence"):
        sub = subs.add_parser(name)
        sub.add_argument("--source", default="materials/requests")
        sub.add_argument("--output", default="deliverables")
        sub.add_argument("--state", help="SQLite path on local durable storage")
        sub.add_argument("--policy", help="policy text to version with the deployed routing implementation")
        if name in ("intake", "resume", "retry", "accuracy", "evidence"):
            sub.add_argument("--mock", action="store_true", help="replay labeled fixtures; no model call")
        if name in ("intake", "retry"):
            sub.add_argument("--documents", nargs="+", help="export filenames")
        if name in ("intake", "resume", "retry"):
            sub.add_argument("--workers", type=int, default=4)
        if name == "intake":
            sub.add_argument("--force", action="store_true")
            sub.add_argument("--submit-only", action="store_true", help="register work and return a resumable batch ID")
        if name == "resume":
            sub.add_argument("batch_id")
            sub.add_argument("--saved-config", action="store_true", help="restore the batch's saved settings")
        if name == "retry":
            sub.add_argument("--current-config", action="store_true", help="intentionally replace saved settings with the current environment")
        if name == "status":
            sub.add_argument("--batch")
        if name == "accuracy":
            sub.add_argument("--expectations", help="source-derived expectation manifest")
            sub.add_argument("--purpose-reviews", help="source-grounded purpose adjudications bound to source/extraction hashes")
            sub.add_argument("--fail-on-errors", action="store_true", help="exit nonzero when any factual/evidence/review quality check fails")
    args = parser.parse_args()
    mock = getattr(args, "mock", False)
    config = {"provider": "mock", "model": "fixtures-v1"} if mock else None
    app = Intake(args.source, args.output, args.state, config=config, policy_path=args.policy)
    if args.command == "resume" and args.saved_config:
        app = app.for_batch(args.batch_id)
        if args.mock and app.extractor.config["provider"] != "mock":
            parser.error("--mock cannot replay saved provider settings; submit a new mock intake")
        mock = app.extractor.config["provider"] == "mock"
    responder = None
    if mock:
        from .fixtures import fixture_response
        responder = fixture_response

    kwargs = {"responder": responder, "response_source": "mock" if mock else None}
    if args.command == "intake":
        docs = args.documents
        if docs and any(Path(d).name != d for d in docs):
            parser.error("documents must be filenames")
        paths = [app.source / d for d in docs] if docs else None
        batch = app.submit(paths, force=args.force)
        # Flushed before any network work: usable after interruption.
        print(json.dumps({"batch_id": batch}), flush=True)
        result = {"batch_id": batch} if args.submit_only else app.resume(batch, workers=args.workers, **kwargs)
    elif args.command == "resume":
        result = app.resume(args.batch_id, workers=args.workers, **kwargs)
    elif args.command == "retry":
        result = app.retry_failed(args.documents, current_config=args.current_config, workers=args.workers, **kwargs)
    elif args.command == "refresh-policy":
        result = app.refresh_policy()
    elif args.command == "status":
        result = {"batches": app.store.batches(), "progress": app.status(args.batch)}
    elif args.command == "queue":
        result = app.queue()
    elif args.command == "export":
        result = app.publish()
    elif args.command == "verify":
        result = app.verify()
    elif args.command == "migrate":
        result = app.import_legacy()
    elif args.command == "accuracy":
        from .accuracy import run_accuracy
        options = {"purpose_reviews_path": args.purpose_reviews}
        if args.expectations:
            options["expectations_path"] = args.expectations
        result = run_accuracy(app, **kwargs, **options)
    else:
        from .reports import write_evidence
        result = write_evidence(app, **kwargs)
    print(json.dumps(result, indent=2))
    if isinstance(result, dict) and result.get("failed"):
        return 1
    if isinstance(result, dict) and result.get("error"):
        return 1
    if args.command == "accuracy" and args.fail_on_errors and not result["passed"]:
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Operator API shared by the notebook and CLI."""

from concurrent.futures import ThreadPoolExecutor
import hashlib
import json
import os
import shlex
from pathlib import Path
import threading
import time
import uuid

from .extraction import (ROOT, ROUTING_VERSION, route_record, routing_source_version,
                         validate_extraction, ExtractionError)
from .provider import Extractor, now
from .store import Store


class Intake:
    def __init__(self, source="materials/requests", output="deliverables", state=None,
                 config=None, lease_seconds=None, policy_path=None):
        self.source, self.output = Path(source), Path(output)
        self.output.mkdir(parents=True, exist_ok=True)
        self.store = Store(state or os.getenv("INTAKE_STATE") or self.output / ".state" / "intake.sqlite3")
        self.extractor = Extractor(config)
        self.policy_path = Path(policy_path or os.getenv("INTAKE_POLICY_PATH") or ROOT / "materials/office-policy.md")
        self.policy_version = self._policy_info()["version"]
        self.lease_seconds = float(lease_seconds if lease_seconds is not None else os.getenv("INTAKE_LEASE_SECONDS", "30"))
        if self.lease_seconds <= 0:
            raise ValueError("lease_seconds must be positive")

    now = staticmethod(now)

    @staticmethod
    def atomic_write(path, text):
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = path.with_name(path.name + ".tmp-" + uuid.uuid4().hex)
        try:
            with temp.open("w", encoding="utf-8") as stream:
                stream.write(text)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temp, path)
            # Persist the directory entry as well as the file contents on POSIX.
            fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
        finally:
            temp.unlink(missing_ok=True)

    def _policy_info(self):
        if routing_source_version() != ROUTING_VERSION:
            raise ValueError("routing implementation changed on disk; restart the operator process")
        policy = self.policy_path.read_text(encoding="utf-8")
        sha = hashlib.sha256(policy.encode()).hexdigest()
        return {"version": f"office-policy@{sha[:12]}/routing@{ROUTING_VERSION[:12]}",
                "policy_sha256": sha, "routing_version": ROUTING_VERSION, "policy_text": policy}

    def _activate_policy(self):
        result = self.store.activate_policy(self._policy_info, self.route)
        self.policy_version = result["policy"]["version"]

    def route(self, record, policy=None):
        policy = policy or self._policy_info()
        if policy["routing_version"] != ROUTING_VERSION:
            raise ValueError("active routing implementation differs; restart the operator process")
        return {**route_record(record, policy["version"]), "routing_version": policy["routing_version"],
                "policy_sha256": policy["policy_sha256"]}

    def refresh_policy(self):
        result = self.store.activate_policy(self._policy_info, self.route, refresh=True)
        self.policy_version = result["policy"]["version"]
        result["queue"] = self.publish()
        return result

    def current(self):
        return self.store.current()

    def submit(self, paths=None, force=False):
        paths = list(paths) if paths is not None else sorted(self.source.glob("*.json"))
        # Capture bytes once. A read failure is a document result, never a
        # fabricated empty source/hash or a reason to stop unrelated messages.
        sources = []
        for path in map(Path, paths):
            try:
                sources.append((path.name, path.read_bytes(), None))
            except OSError as exc:
                sources.append((path.name, None, type(exc).__name__))
        try:
            self.extractor.prepare()
        except ExtractionError:
            pass  # extraction will record an actionable configuration error
        self._activate_policy()
        batch = self.store.submit(sources, self.extractor.fingerprint, self.route, force,
                                  processing_config=self.extractor.metadata())
        self.publish()
        return batch

    def _worker(self, batch, responder, response_source, preparation_error=None):
        while True:
            job = self.store.claim(batch, self.extractor.fingerprint, self.lease_seconds)
            if job is None:
                return
            stop = threading.Event()

            def heartbeat():
                while not stop.wait(self.lease_seconds / 3):
                    if not self.store.renew(job, self.lease_seconds):
                        return

            keeper = threading.Thread(target=heartbeat, daemon=True)
            keeper.start()
            try:
                record = self.extractor.extract(job["document_id"], None if job["input_error"] else job["raw"],
                                                responder, response_source, input_error=job["input_error"],
                                                preparation_error=preparation_error)
                self.store.complete(job, record, self.route)
                # State is committed before publication. resume/export repairs any
                # filesystem interruption without another model call.
                self.publish()
            finally:
                stop.set()
                keeper.join()

    def for_batch(self, batch):
        items = self.store.progress(batch)["items"]
        fingerprints = {i["settings_fingerprint"] for i in items}
        if not items:
            return self
        if len(fingerprints) != 1:
            raise ValueError("batch contains mixed settings; use its original operator configuration")
        extractor = Extractor.from_metadata(items[0]["processing_config"])
        return self._with_extractor(extractor)

    def _with_extractor(self, extractor):
        return Intake(self.source, self.output, self.store.path, config=extractor.config,
                      lease_seconds=self.lease_seconds, policy_path=self.policy_path)

    def resume(self, batch, workers=None, responder=None, response_source=None, saved_config=False):
        if saved_config:
            app = self.for_batch(batch)
            if responder is None and app.extractor.config["provider"] == "mock":
                from .fixtures import fixture_response
                responder, response_source = fixture_response, "mock"
            return app.resume(batch, workers, responder, response_source)
        if responder is not None and not response_source:
            raise ValueError("custom responders must explicitly label response_source")
        if response_source == "mock" and self.extractor.config["provider"] != "mock":
            raise ValueError("mock responses require config={'provider': 'mock', 'model': 'fixtures-v1'}; this prevents reuse as live results")
        preparation_error = None
        try:
            self.extractor.prepare()
        except ExtractionError as exc:
            preparation_error = exc
        progress = self.store.progress(batch)
        incompatible = [i for i in progress["items"] if i["state"] in ("pending", "running")
                        and i["settings_fingerprint"] != self.extractor.fingerprint]
        if incompatible:
            raise ValueError("batch settings differ; restore its original configuration or submit a new intake")
        workers = int(workers if workers is not None else os.getenv("INTAKE_WORKERS", "4"))
        if workers <= 0:
            raise ValueError("workers must be positive")
        self._activate_policy()
        self.publish()
        while True:
            with ThreadPoolExecutor(max_workers=workers) as pool:
                futures = [pool.submit(self._worker, batch, responder, response_source, preparation_error) for _ in range(workers)]
                for future in futures:
                    future.result()
            progress = self.store.progress(batch)
            if not (progress["counts"]["pending"] or progress["counts"]["running"]):
                break
            # Another process may own work. Wait for it, or reclaim after its lease
            # expires. Completed work is already visible through queue()/status().
            time.sleep(min(0.25, self.lease_seconds / 3))
        with self.store.transaction(False) as db:
            reused = [r[0] for r in db.execute("SELECT j.document_id FROM batch_jobs b JOIN jobs j ON j.id=b.job_id WHERE b.batch_id=? AND b.reused=1", (batch,))]
        extracted = sorted(i["document_id"] for i in progress["items"] if i["state"] in ("completed", "failed") and i["document_id"] not in reused)
        return {"batch_id": batch, "extracted": extracted, "reused": sorted(reused),
                "failed": sorted(i["document_id"] for i in progress["items"] if i["state"] == "failed"),
                "progress": progress, "queue": self.queue()}

    def run(self, paths=None, force=False, **kwargs):
        batch = self.submit(paths, force)
        return self.resume(batch, **kwargs)

    def retry_failed(self, document_ids=None, current_config=False, **kwargs):
        current = self.current()
        targets = document_ids if document_ids is not None else sorted(
            d for d, record in current.items() if record.get("error"))
        if any(Path(d).name != d for d in targets):
            raise ValueError("document IDs must be filenames")
        groups = {}
        for doc in sorted(set(targets)):
            extractor = (self.extractor if current_config or doc not in current else
                         Extractor.from_metadata(current[doc].get("processing_config")))
            if kwargs.get("response_source") == "mock" and extractor.config["provider"] != "mock":
                raise ValueError("--mock cannot replay a saved provider configuration; use --current-config --mock to change it explicitly")
            key = json.dumps(extractor.metadata(), sort_keys=True)
            groups.setdefault(key, (extractor, []))[1].append(doc)
        results = []
        for extractor, docs in groups.values():
            app = self._with_extractor(extractor)
            options = dict(kwargs)
            if options.get("responder") is None and extractor.config["provider"] == "mock":
                from .fixtures import fixture_response
                options.update(responder=fixture_response, response_source="mock")
            results.append(app.run([self.source / d for d in docs], force=True, **options))
        if len(results) == 1:
            return results[0]
        return {"batch_ids": [r["batch_id"] for r in results],
                **{k: sorted(d for r in results for d in r[k]) for k in ("extracted", "reused", "failed")},
                "queue": self.queue() if (self.output / "CURRENT.json").exists() else None}

    def status(self, batch=None):
        return self.store.progress(batch)

    def _queue(self, records, generation):
        items, summary = [], {}
        for record in records:
            ex = record.get("extraction") or {}
            item = {k: record.get(k) for k in ("document_id", "source_sha256", "status", "owner", "next_action", "error", "error_details", "source_read_error", "response_source", "last_success", "settings_fingerprint", "processing_config", "policy_version", "routing_version", "routing_history_file", "revision")}
            item.update({k: ex.get(k) for k in ("request_id", "kind", "requester", "team", "system", "environment", "permission", "start_date", "end_date", "manager")})
            command = ["python", "-m", "intake", "retry", "--source", str(self.source.resolve()),
                       "--output", str(self.output.resolve()), "--state", str(self.store.path.resolve()),
                       "--policy", str(self.policy_path.resolve()),
                       "--documents", record["document_id"]]
            if record.get("response_source") == "mock":
                command.append("--mock")
            if not record.get("processing_config"):
                command.append("--current-config")
            item.update(reasons=record.get("routing_reasons", []), issues=ex.get("issues", []),
                        retry_command=shlex.join(command) if record.get("error") else None,
                        generation_id=generation)
            items.append(item)
            key = f"{item['owner']} / {item['next_action']}"
            summary[key] = summary.get(key, 0) + 1
        return {"generation_id": generation, "generated_at": now(), "total": len(items),
                "summary": summary, "items": items,
                "settings_fingerprints": sorted({r["settings_fingerprint"] for r in records}),
                "policy_versions": sorted({r["policy_version"] for r in records})}

    def publish(self, failpoint=None):
        """Publish one immutable pair, then atomically switch CURRENT.json.

        Root JSON files are compatibility exports. Coherent readers use the
        manifest or database; publication after a crash is safe to repeat.
        """
        with self.store.transaction() as db:
            records = list(self.store.records(db).values())
            generation = uuid.uuid4().hex
            for record in records:
                record["generation_id"] = generation
            queue = self._queue(records, generation)
            for row in db.execute("SELECT record FROM attempts"):
                record = json.loads(row[0])
                path = self.output / record["history_file"]
                if not path.exists():
                    self.atomic_write(path, json.dumps(record, indent=2) + "\n")
            for row in db.execute("SELECT record FROM routing_events"):
                event = json.loads(row[0])
                path = self.output / event["history_file"]
                if not path.exists():
                    self.atomic_write(path, json.dumps(event, indent=2) + "\n")
            text = "".join(json.dumps(r, ensure_ascii=False) + "\n" for r in records)
            qtext = json.dumps(queue, indent=2, ensure_ascii=False) + "\n"
            relative = Path("generations") / generation
            self.atomic_write(self.output / relative / "extractions.jsonl", text)
            if failpoint:
                failpoint("after_extractions")
            self.atomic_write(self.output / relative / "queue.json", qtext)
            if failpoint:
                failpoint("before_manifest")
            self.atomic_write(self.output / "CURRENT.json", json.dumps({
                "generation_id": generation,
                "extractions": str(relative / "extractions.jsonl"),
                "queue": str(relative / "queue.json")}) + "\n")
            # These two conventional submission files are individually atomic.
            # Their generation IDs expose a mixed pair to external readers.
            self.atomic_write(self.output / "extractions.jsonl", text)
            self.atomic_write(self.output / "queue.json", qtext)
            return queue

    def snapshot(self):
        manifest = json.loads((self.output / "CURRENT.json").read_text())
        records = [json.loads(line) for line in (self.output / manifest["extractions"]).read_text().splitlines()]
        queue = json.loads((self.output / manifest["queue"]).read_text())
        if queue["generation_id"] != manifest["generation_id"] or any(r["generation_id"] != manifest["generation_id"] for r in records):
            raise ValueError("snapshot generation mismatch")
        return records, queue

    def queue(self):
        return self.snapshot()[1]

    def verify(self, require_complete=True):
        records, queue = self.snapshot()
        by_id = {r["document_id"]: r for r in records}
        items = {r["document_id"]: r for r in queue["items"]}
        assert len(records) == len(by_id) == queue["total"] == len(items)
        assert set(items) == set(by_id)
        if require_complete:
            assert {p.name for p in self.source.glob("*.json")} <= set(by_id), "unfinished sources; inspect status"
        for doc, record in by_id.items():
            for key in ("source_sha256", "status", "owner", "next_action", "error", "response_source", "generation_id"):
                assert record[key] == items[doc][key], (doc, key)
            if record.get("source_read_error"):
                assert record["source_sha256"] is None and record["error"] and record["extraction"] is None
                raw = None  # no source bytes existed for this recorded attempt
            else:
                raw = (self.source / doc).read_bytes()
                assert record["source_sha256"] == hashlib.sha256(raw).hexdigest(), (doc, "source has unprocessed updates")
            if record["error"] is None:
                assert validate_extraction(record["extraction"], json.loads(raw)["message"]) == [], doc
            else:
                assert record["extraction"] is None and record["next_action"] == "retry-extraction", doc
            history = json.loads((self.output / record["history_file"]).read_text())
            assert history["extraction"] == record["extraction"] and history["source_sha256"] == record["source_sha256"]
            if record.get("last_success"):
                assert json.loads((self.output / record["last_success"]["history_file"]).read_text())["error"] is None
            if record.get("routing_history_file"):
                event = json.loads((self.output / record["routing_history_file"]).read_text())
                assert event["after"]["policy_version"] == record["policy_version"]
        return f"PASS: {len(records)} records match their queue, source bytes and history"

    def import_legacy(self):
        """Explicit one-time migration of existing current exports, without calls.

        Keep the originals and their source/configuration provenance. Existing
        history files remain in place; new entries are also archived in SQLite.
        """
        path = self.output / "extractions.jsonl"
        records = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
        if len({r["document_id"] for r in records}) != len(records):
            raise ValueError("legacy exports contain duplicate document IDs")
        self._activate_policy()
        with self.store.transaction() as db:
            if db.execute("SELECT 1 FROM current UNION ALL SELECT 1 FROM jobs LIMIT 1").fetchone():
                raise ValueError("migration requires an empty state database")
            for record in records:
                doc = record["document_id"]
                if Path(doc).name != doc:
                    raise ValueError("invalid document_id")
                raw = (self.source / doc).read_bytes()
                if hashlib.sha256(raw).hexdigest() != record["source_sha256"]:
                    raise ValueError(f"source hash differs for {doc}")
                if record.get("error") is None and validate_extraction(record["extraction"], json.loads(raw)["message"]):
                    raise ValueError(f"invalid legacy extraction for {doc}")
                previous_history = record.get("history_file")
                attempt = uuid.uuid4().hex
                record["history_file"] = f"history/{doc}/{attempt}.json"
                record["imported_from_history"] = previous_history
                record.setdefault("last_success", None)
                record.update(self.route(record))
                self.store.put_current(db, record)
                db.execute("INSERT INTO attempts VALUES (?,NULL,1,?)", (attempt, json.dumps(record)))
        return self.publish()

"""Local durable state. All mutations use short SQLite transactions.

Source order means acceptance order in this store, never export timestamps.
Network filesystems and sharing this file across compute hosts are unsupported.
"""

from contextlib import closing, contextmanager
import hashlib
import json
from pathlib import Path
import sqlite3
import time
import uuid

from .provider import now


class Store:
    def __init__(self, path):
        self.path = Path(path)
        absolute = self.path.resolve()
        if any(absolute == root or root in absolute.parents for root in map(Path, ("/Workspace", "/Volumes", "/dbfs"))):
            raise ValueError("SQLite state must use local persistent disk, not Databricks Workspace/Volumes/DBFS")
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with closing(self.connect()) as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS batches (
                    id TEXT PRIMARY KEY, created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS jobs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    document_id TEXT NOT NULL, sha TEXT NOT NULL,
                    raw BLOB NOT NULL, fingerprint TEXT NOT NULL,
                    state TEXT NOT NULL, token TEXT, lease_until REAL,
                    created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS batch_jobs (
                    batch_id TEXT NOT NULL, job_id INTEGER NOT NULL,
                    reused INTEGER NOT NULL DEFAULT 0,
                    PRIMARY KEY (batch_id, job_id)
                );
                CREATE TABLE IF NOT EXISTS desired (
                    document_id TEXT PRIMARY KEY, job_id INTEGER NOT NULL
                );
                CREATE TABLE IF NOT EXISTS current (
                    document_id TEXT PRIMARY KEY, record TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS attempts (
                    id TEXT PRIMARY KEY, job_id INTEGER,
                    applied INTEGER NOT NULL, record TEXT NOT NULL
                );
                CREATE INDEX IF NOT EXISTS jobs_state ON jobs(state, lease_until);
                CREATE TABLE IF NOT EXISTS policy_versions (
                    version TEXT PRIMARY KEY, metadata TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS active_policy (
                    id INTEGER PRIMARY KEY CHECK (id=1), metadata TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS routing_events (
                    id TEXT PRIMARY KEY, record TEXT NOT NULL
                );
            """)
        # Additive migration of databases created by steps 1–4. Serialize the
        # inspection and ALTERs so simultaneous operator startup is safe.
        with self.transaction() as db:
            columns = {r["name"] for r in db.execute("PRAGMA table_info(jobs)")}
            for column in ("input_error", "processing_config"):
                if column not in columns:
                    db.execute(f"ALTER TABLE jobs ADD COLUMN {column} TEXT")

    def connect(self):
        db = sqlite3.connect(self.path, timeout=30, isolation_level=None)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA synchronous=FULL")
        return db

    @contextmanager
    def transaction(self, write=True):
        db = self.connect()
        try:
            db.execute("BEGIN IMMEDIATE" if write else "BEGIN")
            yield db
            db.commit()
        except BaseException:
            db.rollback()
            raise
        finally:
            db.close()

    @staticmethod
    def records(db):
        return {row["document_id"]: json.loads(row["record"])
                for row in db.execute("SELECT * FROM current ORDER BY document_id")}

    @staticmethod
    def put_current(db, record):
        db.execute("INSERT OR REPLACE INTO current VALUES (?, ?)",
                   (record["document_id"], json.dumps(record)))

    def current(self):
        with self.transaction(False) as db:
            return self.records(db)

    @staticmethod
    def route_current_policy(db, record, route):
        row = db.execute("SELECT metadata FROM active_policy WHERE id=1").fetchone()
        return route(record, policy=json.loads(row[0]) if row else None)

    def reroute(self, db, record, route, policy=None):
        fields = ("status", "owner", "next_action", "routing_reasons", "policy_version", "routing_version", "policy_sha256")
        before = {k: record.get(k) for k in fields}
        routing = route(record, policy=policy) if policy else self.route_current_policy(db, record, route)
        after = {k: routing.get(k) for k in fields}
        if before == after:
            return False
        event_id = uuid.uuid4().hex
        path = f"routing-history/{record['document_id']}/{event_id}.json"
        event = {"document_id": record["document_id"], "source_sha256": record["source_sha256"],
                 "extraction_history_file": record["history_file"], "changed_at": now(),
                 "before": before, "after": after, "history_file": path,
                 "previous_routing_history_file": record.get("routing_history_file")}
        db.execute("INSERT INTO routing_events VALUES (?,?)", (event_id, json.dumps(event)))
        record.update(routing, routing_history_file=path)
        self.put_current(db, record)
        return True

    def activate_policy(self, load_policy, route, refresh=False):
        changed = []
        with self.transaction() as db:
            # Read files while holding the state lock: an old operator cannot
            # activate a cached earlier policy after a newer activation.
            policy = load_policy()
            db.execute("INSERT OR IGNORE INTO policy_versions VALUES (?,?)", (policy["version"], json.dumps(policy)))
            db.execute("INSERT OR REPLACE INTO active_policy VALUES (1,?)", (json.dumps(policy),))
            if refresh:
                for doc, record in self.records(db).items():
                    if self.reroute(db, record, route, policy):
                        changed.append(doc)
        return {"policy": policy, "refreshed": changed}

    def submit(self, sources, fingerprint, route, force=False, processing_config=None):
        """Register byte snapshots atomically; later accepted revisions win.

        Identical active work is shared. Each batch keeps its own membership,
        including reused and superseded work, for progress and resumption.
        """
        batch = uuid.uuid4().hex
        with self.transaction() as db:
            db.execute("INSERT INTO batches VALUES (?, ?)", (batch, now()))
            current = self.records(db)
            seen = set()
            for source in sources:
                doc, raw = source[:2]
                input_error = source[2] if len(source) > 2 else None
                if doc in seen:
                    raise ValueError(f"duplicate document_id in batch: {doc}")
                seen.add(doc)
                sha = hashlib.sha256(raw).hexdigest() if raw is not None else ""
                active = db.execute("SELECT j.* FROM desired d JOIN jobs j ON j.id=d.job_id WHERE d.document_id=?", (doc,)).fetchone()
                same_active = active and active["sha"] == sha and active["input_error"] == input_error and active["fingerprint"] == fingerprint and active["state"] in ("pending", "running")
                if same_active and not force:
                    job_id, reused = active["id"], False
                else:
                    old = current.get(doc)
                    reused = bool(raw is not None and not force and old and old.get("error") is None
                                  and old.get("extraction") is not None
                                  and old.get("source_sha256") == sha
                                  and old.get("settings_fingerprint") == fingerprint)
                    job_id = db.execute("INSERT INTO jobs(document_id,sha,raw,fingerprint,state,created_at,input_error,processing_config) VALUES (?,?,?,?,?,?,?,?)",
                                        (doc, sha, raw if raw is not None else b"", fingerprint, "done" if reused else "pending", now(), input_error,
                                         json.dumps(processing_config) if processing_config else None)).lastrowid
                    if active:
                        db.execute("UPDATE jobs SET state='superseded', token=NULL, lease_until=NULL WHERE id=? AND state IN ('pending','running')", (active["id"],))
                    db.execute("INSERT OR REPLACE INTO desired VALUES (?,?)", (doc, job_id))
                    if reused:
                        self.reroute(db, old, route)
                db.execute("INSERT INTO batch_jobs VALUES (?,?,?)", (batch, job_id, int(reused)))
        return batch

    def claim(self, batch, fingerprint, lease_seconds):
        token = uuid.uuid4().hex
        timestamp = time.time()
        with self.transaction() as db:
            row = db.execute("""SELECT j.* FROM jobs j
                JOIN batch_jobs b ON b.job_id=j.id
                JOIN desired d ON d.job_id=j.id
                WHERE b.batch_id=? AND j.fingerprint=?
                AND (j.state='pending' OR (j.state='running' AND j.lease_until < ?))
                ORDER BY j.id LIMIT 1""", (batch, fingerprint, timestamp)).fetchone()
            if row is None:
                return None
            db.execute("UPDATE jobs SET state='running',token=?,lease_until=? WHERE id=?",
                       (token, timestamp + lease_seconds, row["id"]))
            return {**dict(row), "token": token}

    def renew(self, job, lease_seconds):
        with self.transaction() as db:
            timestamp = time.time()
            changed = db.execute("UPDATE jobs SET lease_until=? WHERE id=? AND token=? AND state='running' AND lease_until>=?",
                                 (timestamp + lease_seconds, job["id"], job["token"], timestamp)).rowcount
            return bool(changed)

    def complete(self, job, record, route):
        attempt_id = uuid.uuid4().hex
        record = dict(record)
        record["revision"] = job["id"]
        record["history_file"] = f"history/{record['document_id']}/{attempt_id}.json"
        with self.transaction() as db:
            record.update(self.route_current_policy(db, record, route))
            live = db.execute("SELECT j.*, d.job_id AS desired_id FROM jobs j LEFT JOIN desired d ON d.document_id=j.document_id WHERE j.id=?", (job["id"],)).fetchone()
            applied = bool(live and live["token"] == job["token"]
                           and live["state"] == "running" and live["desired_id"] == job["id"]
                           and live["lease_until"] >= time.time())
            old_row = db.execute("SELECT record FROM current WHERE document_id=?", (record["document_id"],)).fetchone()
            old = json.loads(old_row[0]) if old_row else None
            record["last_success"] = None
            if record["error"] and old:
                record["last_success"] = ({k: old.get(k) for k in (
                    "history_file", "source_sha256", "settings_fingerprint", "extracted_at", "response_source")}
                    if old.get("error") is None else old.get("last_success"))
            db.execute("INSERT INTO attempts VALUES (?,?,?,?)", (attempt_id, job["id"], int(applied), json.dumps(record)))
            if applied:
                self.put_current(db, record)
                db.execute("UPDATE jobs SET state=?,token=NULL,lease_until=NULL WHERE id=?",
                           ("failed" if record["error"] else "done", job["id"]))
        return applied

    def progress(self, batch=None):
        with self.transaction(False) as db:
            if batch and not db.execute("SELECT 1 FROM batches WHERE id=?", (batch,)).fetchone():
                raise ValueError(f"unknown batch: {batch}")
            rows = db.execute("""SELECT j.*, b.reused, b.batch_id FROM jobs j
                JOIN batch_jobs b ON b.job_id=j.id WHERE b.batch_id=? ORDER BY j.id""", (batch,)).fetchall() if batch else db.execute("SELECT *, 0 AS reused FROM jobs ORDER BY id").fetchall()
            counts = {s: 0 for s in ("pending", "running", "completed", "failed", "superseded", "reused")}
            items = []
            for row in rows:
                state = "completed" if row["state"] == "done" else row["state"]
                counts[state] += 1
                counts["reused"] += row["reused"]
                items.append({"document_id": row["document_id"], "revision": row["id"],
                              "source_sha256": row["sha"] or None, "state": state,
                              "lease_expired": state == "running" and row["lease_until"] < time.time(),
                              "settings_fingerprint": row["fingerprint"], "input_error": row["input_error"],
                              "processing_config": json.loads(row["processing_config"]) if row["processing_config"] else None})
            return {"batch_id": batch, "counts": counts, "items": items}

    def batches(self):
        with self.transaction(False) as db:
            return [dict(r) for r in db.execute("SELECT * FROM batches ORDER BY created_at DESC")]

"""Run with python -m intake; offline operation needs no installation."""

import argparse
import json
from pathlib import Path

from .app import Intake
from .extraction import ROOT


def main():
    parser = argparse.ArgumentParser(description="Durable IT access-request intake")
    subs = parser.add_subparsers(dest="command", required=True)
    for name in ("intake", "resume", "retry", "refresh-policy", "queue", "status", "export", "verify", "migrate", "accuracy", "evidence"):
        sub = subs.add_parser(name)
        sub.add_argument("--source", default="materials/requests")
        sub.add_argument("--output", default="deliverables")
        sub.add_argument("--state", help="SQLite path on local durable storage")
        sub.add_argument("--policy", help="policy text to version with the deployed routing implementation")
        if name in ("intake", "resume", "retry", "accuracy", "evidence"):
            sub.add_argument("--mock", action="store_true", help="replay labeled fixtures; no model call")
        if name in ("intake", "retry"):
            sub.add_argument("--documents", nargs="+", help="export filenames")
        if name in ("intake", "resume", "retry"):
            sub.add_argument("--workers", type=int, default=4)
        if name == "intake":
            sub.add_argument("--force", action="store_true")
            sub.add_argument("--submit-only", action="store_true", help="register work and return a resumable batch ID")
        if name == "resume":
            sub.add_argument("batch_id")
            sub.add_argument("--saved-config", action="store_true", help="restore the batch's saved settings")
        if name == "retry":
            sub.add_argument("--current-config", action="store_true", help="intentionally replace saved settings with the current environment")
        if name == "status":
            sub.add_argument("--batch")
        if name == "accuracy":
            sub.add_argument("--expectations", help="source-derived expectation manifest")
            sub.add_argument("--purpose-reviews", help="source-grounded purpose adjudications bound to source/extraction hashes")
            sub.add_argument("--fail-on-errors", action="store_true", help="exit nonzero when any factual/evidence/review quality check fails")
    args = parser.parse_args()
    mock = getattr(args, "mock", False)
    config = {"provider": "mock", "model": "fixtures-v1"} if mock else None
    app = Intake(args.source, args.output, args.state, config=config, policy_path=args.policy)
    if args.command == "resume" and args.saved_config:
        app = app.for_batch(args.batch_id)
        if args.mock and app.extractor.config["provider"] != "mock":
            parser.error("--mock cannot replay saved provider settings; submit a new mock intake")
        mock = app.extractor.config["provider"] == "mock"
    responder = None
    if mock:
        from .fixtures import fixture_response
        responder = fixture_response

    kwargs = {"responder": responder, "response_source": "mock" if mock else None}
    if args.command == "intake":
        docs = args.documents
        if docs and any(Path(d).name != d for d in docs):
            parser.error("documents must be filenames")
        paths = [app.source / d for d in docs] if docs else None
        batch = app.submit(paths, force=args.force)
        # Flushed before any network work: usable after interruption.
        print(json.dumps({"batch_id": batch}), flush=True)
        result = {"batch_id": batch} if args.submit_only else app.resume(batch, workers=args.workers, **kwargs)
    elif args.command == "resume":
        result = app.resume(args.batch_id, workers=args.workers, **kwargs)
    elif args.command == "retry":
        result = app.retry_failed(args.documents, current_config=args.current_config, workers=args.workers, **kwargs)
    elif args.command == "refresh-policy":
        result = app.refresh_policy()
    elif args.command == "status":
        result = {"batches": app.store.batches(), "progress": app.status(args.batch)}
    elif args.command == "queue":
        result = app.queue()
    elif args.command == "export":
        result = app.publish()
    elif args.command == "verify":
        result = app.verify()
    elif args.command == "migrate":
        result = app.import_legacy()
    elif args.command == "accuracy":
        from .accuracy import run_accuracy
        options = {"purpose_reviews_path": args.purpose_reviews}
        if args.expectations:
            options["expectations_path"] = args.expectations
        result = run_accuracy(app, **kwargs, **options)
    else:
        from .reports import write_evidence
        result = write_evidence(app, **kwargs)
    print(json.dumps(result, indent=2))
    if isinstance(result, dict) and result.get("failed"):
        return 1
    if isinstance(result, dict) and result.get("error"):
        return 1
    if args.command == "accuracy" and args.fail_on_errors and not result["passed"]:
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
